console.log('All tau2Airline flights:');
flights.forEach(f => {
  console.log(f.flight_id, f.origin, '->', f.destination, 'status:', f.status, 'stops:', f.stops, 'dates:', f.dates_json, 'prices:', f.cabin_prices_json);
});
"

