NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get unique origins and destinations
const routes = db.prepare('SELECT DISTINCT origin, destination FROM flights WHERE source_skill = ?').all('tau2Airline');
console.log('Unique routes:');
routes.forEach(r => console.log(r.origin, '->', r.destination));

// Check for BOS (Boston) flights
const bosFlights = db.prepare(\"SELECT * FROM flights WHERE source_skill = 'tau2Airline' AND (origin = 'BOS' OR destination = 'BOS')\").all();
console.log('\nBoston flights:', bosFlights.length);

// Get all unique airports
const airports = new Set();
routes.forEach(r => { airports.add(r.origin); airports.add(r.destination); });
console.log('\nAll airports:', [...airports].sort().join(', '));
"

NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for James Okafor or similar in users
const users = db.prepare(\"SELECT user_id, name, email, address_json FROM users WHERE name LIKE '%Okafor%' OR name LIKE '%James%' OR email LIKE '%okafor%'\").all();
console.log('Matching users:', JSON.stringify(users, null, 2));

// Also look at the skill_ids_json for tau2Airline users
const tau2Users = db.prepare(\"SELECT user_id, name, email, address_json, skill_ids_json FROM users WHERE skill_ids_json LIKE '%tau2Airline%'\").all();
console.log('\ntau2Airline users count:', tau2Users.length);
tau2Users.forEach(u => console.log(u.user_id, u.name, u.email));
" 2>&1 | head -60

NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if James Okafor from employee data maps to any tau2Airline user
// Also check the flight_bookings for user context
const bookings = db.prepare(\"SELECT * FROM flight_bookings WHERE source_skill = 'tau2Airline'\").all();
console.log('Bookings count:', bookings.length);
bookings.slice(0, 3).forEach(b => console.log(b.booking_id, b.user_id, b.origin, '->', b.destination));

// Check all flights from any airport to BOS
const toBos = db.prepare(\"SELECT * FROM flights WHERE destination = 'BOS' AND source_skill = 'tau2Airline'\").all();
console.log('\nFlights to BOS:', toBos.length);

// Check all unique airports that exist in flights
const origins = db.prepare(\"SELECT DISTINCT origin FROM flights WHERE source_skill = 'tau2Airline'\").all();
const dests = db.prepare(\"SELECT DISTINCT destination FROM flights WHERE source_skill = 'tau2Airline'\").all();
console.log('Origins:', origins.map(o => o.origin));
console.log('Destinations:', dests.map(d => d.destination));
"
